def topo_sort(graph):
    visited = set()
    in_stack = set()
    result = []

    def dfs(node):
        visited.add(node)
        in_stack.add(node)
        for dep in graph.get(node, []):
            if dep not in visited:
                if dfs(dep) is None:
                    return None
            elif dep in in_stack:
                return None
        result.append(node)
        in_stack.remove(node)
        return True

    for node in graph:
        if node not in visited:
            if dfs(node) is None:
                return None
    return result
```

