def normalize(path):
    parts = path.split('/')
    result = []
    is_abs = path.startswith('/')

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if is_abs:
                if result:
                    result.pop()
            else:
                if result and result[-1] != '..':
                    result.pop()
                else:
                    result.append('..')
        else:
            result.append(part)

    if is_abs:
        return '/' if not result else '/' + '/'.join(result)
    else:
        return '.' if not result else '/'.join(result)
```

