def strip_comments(code):
    result = []
    for line in code.splitlines(keepends=True):
        line_out = []
        in_string = False
        quote_char = None
        i = 0
        n = len(line)
        while i < n:
            char = line[i]
            if in_string:
                line_out.append(char)
                if char == '\\':
                    i += 1
                    if i < n:
                        line_out.append(line[i])
                elif char == quote_char:
                    in_string = False
            else:
                if char in ('"', "'"):
                    line_out.append(char)
                    in_string = True
                    quote_char = char
                elif char == '#':
                    break
                else:
                    line_out.append(char)
            i += 1
        result.append(''.join(line_out))
    return ''.join(result)
```

