function debounceCount(fn, ms) {
  let timer = null;
  let lastArgs = [];
  let lastCtx = null;

  const call = function(...args) {
    lastArgs = args;
    lastCtx = this;
    clearTimeout(timer);
    timer = setTimeout(() => {
      fn.apply(lastCtx, lastArgs);
      timer = null;
    }, ms);
  };

  const flush = function() {
    if (timer !== null) {
      clearTimeout(timer);
      fn.apply(lastCtx, lastArgs);
      timer = null;
    }
  };

  return { call, flush };
}

module.exports = debounceCount;
