function parseQuery(qs) {
  if (typeof qs !== 'string') return {};
  if (qs.startsWith('?')) qs = qs.slice(1);
  const result = {};
  for (const pair of qs.split('&')) {
    if (pair === '') continue;
    const idx = pair.indexOf('=');
    const key = idx === -1 ? pair.slice(0) : pair.slice(0, idx);
    const value = idx === -1 ? '' : pair.slice(idx + 1);
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    const decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

    if (result[decodedKey] === undefined) {
      result[decodedKey] = decodedValue;
    } else {
      const curr = result[decodedKey];
      result[decodedKey] = typeof curr === 'string' ? [curr, decodedValue] : [...curr, decodedValue];
    }
  }
  return result;
}

module.exports = { parseQuery };
```

