function mergeDeep(a, b) {
  const result = Array.isArray(a) ? [] : {};
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
  for (const key of keys) {
    const aVal = a[key];
    const bVal = b[key];
    result[key] = (
      typeof bVal === 'object' && bVal !== null && typeof aVal === 'object' && aVal !== null
        ? mergeDeep(aVal, bVal)
        : typeof bVal === 'object' && bVal !== null
          ? deepClone(bVal)
          : (bVal !== undefined ? bVal : aVal)
    );
  }
  return result;
}

function deepClone(val) {
  if (typeof val !== 'object' || val === null) return val;
  const res = Array.isArray(val) ? [] : {};
  for (const k of Object.keys(val)) {
    res[k] = typeof val[k] === 'object' && val[k] !== null ? deepClone(val[k]) : val[k];
  }
  return res;
}

module.exports = mergeDeep;
