```javascript
function deepClone(v, memo = new WeakMap()) {
    if (v === null || typeof v !== 'object') {
        return v;
    }

    if (memo.has(v)) {
        return memo.get(v);
    }

    let clone;

    if (v instanceof Date) {
        clone = new Date(v.getTime());
    } else if (v instanceof RegExp) {
        clone = new RegExp(v.source, v.flags);
    } else if (v instanceof Map) {
        clone = new Map();
        v.forEach((val, key) => {
            clone.set(deepClone(key, memo), deepClone(val, memo));
        });
    } else if (v instanceof Set) {
        clone = new Set();
        v.forEach(val => {
            clone.add(deepClone(val, memo));
        });
    } else if (Array.isArray(v)) {
        clone = new Array(v.length);
        v.forEach((val, i) => {
            clone[i] = deepClone(val, memo);
        });
    } else {
        const descriptors = Object.getOwnPropertyDescriptors(v);
        const clonedDescriptors = {};
        for (const name of Object.keys(descriptors)) {
            const descriptor = descriptors[name];
            if (descriptor.value !== undefined) {
                descriptor.value = deepClone(descriptor.value, memo);
            }
            clonedDescriptors[name] = descriptor;
        }
        clone = Object.defineProperties(Object.create(Object.getPrototypeOf(v)), clonedDescriptors);
    }

    memo.set(v, clone);
    return clone;
}

module.exports = { deepClone };
```

