export function debounceState(): { pending: boolean; mark: () => void; clear: () => void } {
    let state = false;
    let timer: ReturnType<typeof setTimeout> | null = null;

    return {
        get pending(): boolean {
            return state;
        },
        mark(): void {
            if (timer) {
                clearTimeout(timer);
            }
            state = true;
            timer = setTimeout(() => {
                state = false;
                timer = null;
            }, 0);
        },
        clear(): void {
            if (timer) {
                clearTimeout(timer);
            }
            state = false;
            timer = null;
        }
    };
}
```

