import React, { useRef, useState } from 'react';
import { View, Text, Button } from 'react-native';

export default function MutableCounterComponent() {
  const mutableCounter = useRef(0);
  const [renderTrigger, setRenderTrigger] = useState(0);

  const incrementWithoutReRender = () => {
    mutableCounter.current += 1;
  };

  const forceReRender = () => {
    setRenderTrigger(prev => prev + 1);
  };

  return (
    <View style={{ padding: 20 }}>
      <Text>Ref Value (No Re-render): {mutableCounter.current}</Text>
      <Button onPress={incrementWithoutReRender} title="Increment via Ref" />

      <Text style={{ marginTop: 20 }}>State Value (Re-renders): {renderTrigger}</Text>
      <Button onPress={forceReRender} title="Trigger Re-render" />
    </View>
  );
}
```

